begin;
update nexora.modules set description='Planeje, configure e publique sites WordPress com arquitetura editorial, plugins escolhidos por critério, SEO, desempenho, segurança e manutenção.' where course_id=(select id from nexora.courses where slug='programador-master') and position=6;
update nexora.lessons set objective='Explicar a arquitetura básica do WordPress e avaliar quando um CMS atende melhor que uma aplicação desenvolvida do zero.',estimated_minutes=32,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual cenário combina melhor com WordPress?","options":["Site gerenciável com páginas, posts e mídia.","Algoritmo embarcado em dispositivo.","Banco sem interface."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um cliente precisa publicar páginas, notícias e mídia com autonomia. O desafio é decidir se vale construir um painel próprio ou usar um CMS."},{"type":"concept","title":"WordPress: arquitetura e casos de uso","body":"WordPress é um CMS que combina núcleo, banco de dados, temas e plugins para administrar conteúdo e apresentação. Ele é forte quando usuários não técnicos precisam editar conteúdo, quando o problema se encaixa bem em páginas/posts e quando o ecossistema reduz tempo de implementação. Não é automaticamente a melhor escolha para qualquer sistema: regras de negócio muito específicas podem exigir outra arquitetura."},{"type":"mechanics","title":"Critérios práticos","items":["Separe conteúdo, apresentação e extensões.","Avalie requisitos antes de instalar plugins.","Use WordPress quando o CMS reduz complexidade real.","Evite transformar o CMS em solução para um problema que é essencialmente uma aplicação customizada."]},{"type":"example","title":"Aplicação","body":"Site institucional com páginas, blog, equipe e formulário é um bom caso de uso. Um sistema transacional complexo com regras próprias pode exigir backend específico."},{"type":"mistake","title":"Erro comum","body":"Escolher WordPress apenas porque é rápido de instalar, sem avaliar manutenção, segurança e fluxo editorial."},{"type":"guided","question":"Qual cenário combina melhor com WordPress?","options":["Site gerenciável com páginas, posts e mídia.","Algoritmo embarcado em dispositivo.","Banco sem interface."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Explicar a arquitetura básica do WordPress e avaliar quando um CMS atende melhor que uma aplicação desenvolvida do zero.","Separe conteúdo, apresentação e extensões.","Avalie requisitos antes de instalar plugins.","Use WordPress quando o CMS reduz complexidade real."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='WordPress: arquitetura e casos de uso';
update nexora.lessons set objective='Configurar uma instalação WordPress com URL, idioma, permalinks, usuário administrador e ambiente separados de forma segura.',estimated_minutes=36,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual prática reduz risco durante configuração e atualização?","options":["Usar staging e backup.","Editar produção sem cópia.","Compartilhar uma única conta admin."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O site foi instalado com usuário admin genérico, permalinks padrão e configurações de ambiente indefinidas."},{"type":"concept","title":"Instalação e configuração inicial","body":"A configuração inicial estabelece a base operacional do site. URL, idioma, fuso, estrutura de links e usuários afetam conteúdo e manutenção. Em desenvolvimento, o ambiente local/staging deve ser separado de produção. Credenciais fortes e administração mínima reduzem superfície de ataque. Antes de personalizar, confirme que a instalação e os backups funcionam."},{"type":"mechanics","title":"Critérios práticos","items":["Use conta administrativa individual e senha forte.","Configure permalinks legíveis.","Separe desenvolvimento/staging de produção.","Registre configurações críticas e procedimento de backup."]},{"type":"example","title":"Aplicação","body":"Checklist inicial: título/URL → idioma/fuso → permalinks → usuários → tema base → backup → atualizações."},{"type":"mistake","title":"Erro comum","body":"Fazer customização diretamente em produção sem staging ou ponto de restauração."},{"type":"guided","question":"Qual prática reduz risco durante configuração e atualização?","options":["Usar staging e backup.","Editar produção sem cópia.","Compartilhar uma única conta admin."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Configurar uma instalação WordPress com URL, idioma, permalinks, usuário administrador e ambiente separados de forma segura.","Use conta administrativa individual e senha forte.","Configure permalinks legíveis.","Separe desenvolvimento/staging de produção."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Instalação e configuração inicial';
update nexora.lessons set objective='Administrar usuários e papéis aplicando princípio do menor privilégio e distinguindo edição de conteúdo de administração técnica.',estimated_minutes=38,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual princípio deve orientar permissões?","options":["Menor privilégio.","Todos administradores.","Acesso por senha compartilhada."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Todo colaborador recebeu papel de administrador porque era mais simples. Agora qualquer pessoa pode instalar plugins e alterar configurações críticas."},{"type":"concept","title":"Painel, usuários e permissões","body":"Papéis e capacidades controlam o que cada usuário pode fazer. O princípio do menor privilégio diz que cada pessoa recebe apenas permissões necessárias. Autores e editores podem gerenciar conteúdo sem acesso a configurações do site. Administração deve ser restrita e contas inativas removidas. Isso reduz acidentes e impacto de credenciais comprometidas."},{"type":"mechanics","title":"Critérios práticos","items":["Atribua papel conforme responsabilidade.","Evite contas compartilhadas.","Revise usuários periodicamente.","Mantenha poucos administradores."]},{"type":"example","title":"Aplicação","body":"Redator publica próprios textos como Autor; equipe editorial revisa como Editor; manutenção técnica usa Administrador apenas quando necessário."},{"type":"mistake","title":"Erro comum","body":"Dar Administrador para resolver rapidamente um problema de permissão. A exceção temporária vira risco permanente."},{"type":"guided","question":"Qual princípio deve orientar permissões?","options":["Menor privilégio.","Todos administradores.","Acesso por senha compartilhada."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Administrar usuários e papéis aplicando princípio do menor privilégio e distinguindo edição de conteúdo de administração técnica.","Atribua papel conforme responsabilidade.","Evite contas compartilhadas.","Revise usuários periodicamente."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Painel, usuários e permissões';
update nexora.lessons set objective='Escolher entre páginas e posts, organizar taxonomias e mídia para manter conteúdo encontrável e reutilizável.',estimated_minutes=38,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual tipo é mais adequado para uma notícia recorrente?","options":["Post.","Página estática.","Plugin."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um site usa posts para páginas institucionais e dezenas de categorias quase vazias, tornando navegação e manutenção confusas."},{"type":"concept","title":"Páginas, posts, categorias e mídia","body":"Páginas atendem conteúdo relativamente estático e hierárquico; posts são conteúdos cronológicos e classificáveis. Categorias e tags ajudam descoberta quando representam uma taxonomia útil, não quando são criadas sem critério. A biblioteca de mídia deve ter nomes, tamanhos e textos alternativos adequados. Organização editorial impacta SEO e experiência de quem administra."},{"type":"mechanics","title":"Critérios práticos","items":["Use páginas para conteúdo institucional estável.","Use posts para conteúdo editorial recorrente.","Crie categorias com propósito de navegação.","Otimize e descreva mídia antes do upload."]},{"type":"example","title":"Aplicação","body":"Sobre/Contato → páginas. Artigos/notícias → posts. Categoria ''Tutoriais'' só existe se agrupa conteúdo suficiente e ajuda o usuário."},{"type":"mistake","title":"Erro comum","body":"Criar categoria para cada post. Isso não organiza; apenas espalha conteúdo em arquivos vazios."},{"type":"guided","question":"Qual tipo é mais adequado para uma notícia recorrente?","options":["Post.","Página estática.","Plugin."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Escolher entre páginas e posts, organizar taxonomias e mídia para manter conteúdo encontrável e reutilizável.","Use páginas para conteúdo institucional estável.","Use posts para conteúdo editorial recorrente.","Crie categorias com propósito de navegação."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Páginas, posts, categorias e mídia';
update nexora.lessons set objective='Personalizar apresentação por tema e child theme quando necessário, evitando alterações que sejam perdidas em atualizações.',estimated_minutes=42,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual prática protege customizações de código de um tema pai?","options":["Usar child theme/estratégia suportada.","Desativar atualizações para sempre.","Editar arquivos do core."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um arquivo do tema foi editado diretamente. Após atualizar, a alteração desapareceu."},{"type":"concept","title":"Temas e personalização","body":"Temas controlam apresentação e templates. Customizações simples podem usar recursos do próprio tema e editor; alterações de código em tema de terceiros devem considerar child theme ou outra extensão adequada para não serem sobrescritas. Quanto mais um tema é customizado, maior a responsabilidade de testar atualizações e documentar dependências."},{"type":"mechanics","title":"Critérios práticos","items":["Prefira configurações suportadas antes de editar código.","Use child theme para customizações de código em tema pai quando apropriado.","Não misture regra de negócio complexa no tema.","Teste atualização em staging."]},{"type":"example","title":"Aplicação","body":"Ajustes de identidade podem viver no sistema de estilos; uma modificação persistente de template em tema de terceiros pede estratégia que sobreviva a update."},{"type":"mistake","title":"Erro comum","body":"Alterar functions.php ou template do tema pai diretamente em produção."},{"type":"guided","question":"Qual prática protege customizações de código de um tema pai?","options":["Usar child theme/estratégia suportada.","Desativar atualizações para sempre.","Editar arquivos do core."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Personalizar apresentação por tema e child theme quando necessário, evitando alterações que sejam perdidas em atualizações.","Prefira configurações suportadas antes de editar código.","Use child theme para customizações de código em tema pai quando apropriado.","Não misture regra de negócio complexa no tema."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Temas e personalização';
update nexora.lessons set objective='Construir navegação e áreas de conteúdo usando blocos e estruturas reutilizáveis sem duplicar componentes manualmente.',estimated_minutes=38,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual benefício principal de um padrão reutilizável?","options":["Consistência e manutenção centralizada.","Mais plugins obrigatórios.","Desativar o editor."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O mesmo CTA foi copiado em dez páginas; agora uma mudança exige editar todas individualmente."},{"type":"concept","title":"Menus, widgets e blocos","body":"A experiência moderna do WordPress é fortemente baseada em blocos e padrões reutilizáveis. Navegação, áreas de conteúdo e componentes recorrentes devem ser modelados para edição consistente. O objetivo não é usar o maior número de blocos, mas transformar padrões repetidos em unidades controláveis."},{"type":"mechanics","title":"Critérios práticos","items":["Use navegação com rótulos curtos e hierarquia clara.","Reutilize padrões para seções repetidas.","Evite widgets/plugins para algo que blocos nativos resolvem.","Teste edição pelo usuário responsável pelo conteúdo."]},{"type":"example","title":"Aplicação","body":"Um padrão de CTA com título, texto e botão pode ser reutilizado mantendo estrutura e identidade, enquanto conteúdo autorizado continua editável."},{"type":"mistake","title":"Erro comum","body":"Criar cada seção como composição única sem padrão; a consistência se perde na segunda rodada de edição."},{"type":"guided","question":"Qual benefício principal de um padrão reutilizável?","options":["Consistência e manutenção centralizada.","Mais plugins obrigatórios.","Desativar o editor."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Construir navegação e áreas de conteúdo usando blocos e estruturas reutilizáveis sem duplicar componentes manualmente.","Use navegação com rótulos curtos e hierarquia clara.","Reutilize padrões para seções repetidas.","Evite widgets/plugins para algo que blocos nativos resolvem."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Menus, widgets e blocos';
update nexora.lessons set objective='Avaliar plugins por necessidade, manutenção, segurança e sobreposição de funcionalidades antes de instalar.',estimated_minutes=44,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual deve ser o primeiro critério para instalar um plugin?","options":["Existe uma necessidade real não atendida.","Ele tem um ícone bonito.","Ele adiciona muitos menus."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O site possui três plugins de cache, dois construtores e extensões abandonadas. Conflitos e desempenho pioraram."},{"type":"concept","title":"Plugins e critérios de escolha","body":"Plugins ampliam o WordPress, mas cada extensão adiciona código, dependências e superfície de manutenção. A decisão deve começar pela necessidade: o core ou o tema já resolve? O plugin é mantido, compatível e bem documentado? Há sobreposição com outra extensão? Menos plugins não significa automaticamente melhor, mas redundância e abandono são sinais de risco."},{"type":"mechanics","title":"Critérios práticos","items":["Instale por requisito, não por curiosidade.","Prefira plugins mantidos e com documentação clara.","Evite funções duplicadas entre extensões.","Remova plugins inativos desnecessários."]},{"type":"example","title":"Aplicação","body":"Antes de instalar um plugin de formulário, verifique requisitos de campos, anti-spam, armazenamento, integração e manutenção — não apenas número de downloads."},{"type":"mistake","title":"Erro comum","body":"Instalar vários plugins para testar em produção e deixá-los desativados indefinidamente."},{"type":"guided","question":"Qual deve ser o primeiro critério para instalar um plugin?","options":["Existe uma necessidade real não atendida.","Ele tem um ícone bonito.","Ele adiciona muitos menus."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Avaliar plugins por necessidade, manutenção, segurança e sobreposição de funcionalidades antes de instalar.","Instale por requisito, não por curiosidade.","Prefira plugins mantidos e com documentação clara.","Evite funções duplicadas entre extensões."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Plugins e critérios de escolha';
update nexora.lessons set objective='Configurar formulários com campos mínimos, consentimento e fluxo de tratamento dos dados, testando entrega e falhas.',estimated_minutes=42,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual princípio melhora conversão e privacidade?","options":["Coletar somente dados necessários.","Adicionar todos os campos possíveis.","Ocultar o destino dos dados."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O formulário coleta dez campos, mas o processo comercial usa apenas quatro. A taxa de conclusão cai e ninguém sabe onde os dados ficam."},{"type":"concept","title":"Formulários e captação de dados","body":"Formulários devem coletar o mínimo necessário para o objetivo. Cada campo precisa de propósito, validação e destino. Também é importante definir o que acontece após o envio: mensagem de sucesso, e-mail, CRM, armazenamento, proteção anti-spam e tratamento de erros. Captação não termina no botão enviar."},{"type":"mechanics","title":"Critérios práticos","items":["Reduza campos ao necessário.","Associe labels e mensagens de erro.","Defina destino e responsável pelos dados.","Teste envio, spam, falha e confirmação."]},{"type":"example","title":"Aplicação","body":"Lead simples: nome, WhatsApp/e-mail e interesse. Depois do submit: validação → anti-spam → registro → confirmação → notificação da equipe."},{"type":"mistake","title":"Erro comum","body":"Adicionar CPF, endereço ou outros dados sem necessidade operacional concreta."},{"type":"guided","question":"Qual princípio melhora conversão e privacidade?","options":["Coletar somente dados necessários.","Adicionar todos os campos possíveis.","Ocultar o destino dos dados."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Configurar formulários com campos mínimos, consentimento e fluxo de tratamento dos dados, testando entrega e falhas.","Reduza campos ao necessário.","Associe labels e mensagens de erro.","Defina destino e responsável pelos dados."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Formulários e captação de dados';
update nexora.lessons set objective='Configurar fundamentos de indexação, títulos, headings, URLs, sitemap e metadados sem tratar plugin de SEO como substituto de conteúdo e arquitetura.',estimated_minutes=44,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Um plugin de SEO substitui uma boa arquitetura de conteúdo?","options":["Não.","Sim, sempre.","Somente no mobile."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O site instalou um plugin de SEO, mas possui títulos duplicados, headings incoerentes e páginas importantes sem links internos."},{"type":"concept","title":"SEO técnico básico","body":"SEO técnico básico começa com conteúdo acessível ao crawler, URLs estáveis, title e description úteis, hierarquia de headings, sitemap e links internos. Plugins ajudam a configurar, mas não corrigem arquitetura ruim ou conteúdo fraco. Também é necessário evitar indexar páginas que não deveriam aparecer e garantir canonical quando houver duplicidade relevante."},{"type":"mechanics","title":"Critérios práticos","items":["Use title único e descritivo.","Mantenha um h1 coerente por página.","Crie links internos que reflitam a arquitetura.","Confirme sitemap e indexação."]},{"type":"example","title":"Aplicação","body":"Página Curso JavaScript: URL legível, title específico, h1 alinhado ao tema, description útil e links para módulos relacionados."},{"type":"mistake","title":"Erro comum","body":"Perseguir pontuação verde de plugin enquanto conteúdo e intenção de busca não são atendidos."},{"type":"guided","question":"Um plugin de SEO substitui uma boa arquitetura de conteúdo?","options":["Não.","Sim, sempre.","Somente no mobile."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Configurar fundamentos de indexação, títulos, headings, URLs, sitemap e metadados sem tratar plugin de SEO como substituto de conteúdo e arquitetura.","Use title único e descritivo.","Mantenha um h1 coerente por página.","Crie links internos que reflitam a arquitetura."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='SEO técnico básico';
update nexora.lessons set objective='Diagnosticar gargalos de carregamento e aplicar otimização de imagens, cache e quantidade de recursos sem duplicar mecanismos.',estimated_minutes=46,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual primeira ação é adequada ao otimizar desempenho?","options":["Medir e localizar gargalo.","Instalar três plugins de cache.","Converter todo texto em imagem."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A home baixa imagens enormes e executa scripts de plugins que não são usados na página."},{"type":"concept","title":"Desempenho, cache e imagens","body":"Desempenho depende do peso de imagens, quantidade e custo de scripts, consultas, hospedagem e cache. Otimização eficaz começa medindo. Imagens devem ser dimensionadas e comprimidas; formatos modernos ajudam. Cache reduz trabalho repetido, mas múltiplos plugins de cache podem conflitar. Desempenho é orçamento: cada plugin e recurso consome parte dele."},{"type":"mechanics","title":"Critérios práticos","items":["Meça antes e depois.","Redimensione imagens para o uso real.","Evite scripts e plugins redundantes.","Use uma estratégia de cache coerente."]},{"type":"example","title":"Aplicação","body":"Uma hero de 4000px não deve ser enviada integralmente para um viewport pequeno se versões responsivas podem atender o mesmo resultado."},{"type":"mistake","title":"Erro comum","body":"Ativar várias camadas de minificação/cache sem saber qual controla o quê; bugs ficam difíceis de reproduzir."},{"type":"guided","question":"Qual primeira ação é adequada ao otimizar desempenho?","options":["Medir e localizar gargalo.","Instalar três plugins de cache.","Converter todo texto em imagem."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Diagnosticar gargalos de carregamento e aplicar otimização de imagens, cache e quantidade de recursos sem duplicar mecanismos.","Meça antes e depois.","Redimensione imagens para o uso real.","Evite scripts e plugins redundantes."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Desempenho, cache e imagens';
update nexora.lessons set objective='Manter WordPress atualizado com backups testados, menor privilégio e procedimento de restauração, reduzindo risco operacional.',estimated_minutes=48,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Quando um backup é realmente confiável?","options":["Quando a restauração foi testada.","Quando o arquivo existe.","Quando está no mesmo disco apenas."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma atualização quebra o site e existe um backup, mas ninguém sabe restaurá-lo."},{"type":"concept","title":"Segurança, backup e atualizações","body":"Segurança operacional combina atualizações, contas protegidas, extensões mantidas, backups e capacidade de restauração. Backup só é útil se contém o necessário e o procedimento de recuperação foi testado. Atualizações devem ser aplicadas com ponto de restauração e, em sites críticos, validadas em staging. Logs e monitoramento ajudam a perceber alterações inesperadas."},{"type":"mechanics","title":"Critérios práticos","items":["Atualize core, temas e plugins mantidos.","Faça backup de arquivos e banco conforme a arquitetura.","Teste restauração periodicamente.","Remova contas e extensões desnecessárias."]},{"type":"example","title":"Aplicação","body":"Rotina: backup automático + cópia fora do servidor + teste de restore + staging para atualização relevante + smoke test pós-update."},{"type":"mistake","title":"Erro comum","body":"Não atualizar por medo de quebrar. Adiar indefinidamente também acumula vulnerabilidades e incompatibilidades."},{"type":"guided","question":"Quando um backup é realmente confiável?","options":["Quando a restauração foi testada.","Quando o arquivo existe.","Quando está no mesmo disco apenas."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Manter WordPress atualizado com backups testados, menor privilégio e procedimento de restauração, reduzindo risco operacional.","Atualize core, temas e plugins mantidos.","Faça backup de arquivos e banco conforme a arquitetura.","Teste restauração periodicamente."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Segurança, backup e atualizações';
update nexora.lessons set objective='Planejar, configurar, publicar e documentar um site WordPress profissional com conteúdo editável, desempenho e manutenção considerados.',estimated_minutes=65,lab_type='project',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A entrega precisa ser utilizável por um cliente real, não apenas uma instalação com tema demo."},{"type":"concept","title":"Projeto: site profissional publicado","body":"O projeto deve demonstrar arquitetura editorial, identidade coerente, navegação, formulário funcional, SEO técnico básico, desempenho aceitável e plano de manutenção. O resultado precisa ser editável por um usuário com permissões adequadas. A publicação inclui domínio/HTTPS quando aplicável, backup e smoke test."},{"type":"mechanics","title":"Critérios práticos","items":["Defina mapa de páginas e conteúdo antes de personalizar.","Escolha tema/plugins por requisito.","Configure usuários e formulário com segurança.","Teste publicação, mobile, desempenho e backup."]},{"type":"example","title":"Aplicação","body":"Entrega: site institucional publicado + usuário editor + formulário testado + sitemap + backup + documento curto de manutenção."},{"type":"mistake","title":"Erro comum","body":"Entregar apenas o acesso admin sem documentação, backup ou definição de quem pode editar o quê."},{"type":"guided","question":"O que diferencia um site profissional de uma instalação demo?","options":["Conteúdo, fluxo, segurança e manutenção validados.","Quantidade de plugins.","Tema mais caro."],"answer":0,"hint":"Escolha a opção que reduz risco de manutenção.","feedback":"Correto. A decisão trata WordPress como produto operável, não apenas editor visual.","feedback_incorrect":"Revise necessidade, segurança e manutenção."},{"type":"recap","items":["Planejar, configurar, publicar e documentar um site WordPress profissional com conteúdo editável, desempenho e manutenção considerados.","Defina mapa de páginas e conteúdo antes de personalizar.","Escolha tema/plugins por requisito.","Configure usuários e formulário com segurança."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=6) and title='Projeto: site profissional publicado';

